package twizzy.tech.commands.backpack

import eu.koboo.minestom.stomui.api.PlayerView
import eu.koboo.minestom.stomui.api.ViewBuilder
import eu.koboo.minestom.stomui.api.ViewRegistry
import eu.koboo.minestom.stomui.api.ViewType
import eu.koboo.minestom.stomui.api.component.ViewProvider
import eu.koboo.minestom.stomui.api.interaction.Interaction
import eu.koboo.minestom.stomui.api.interaction.ViewAction
import eu.koboo.minestom.stomui.api.item.ModifiableItem
import eu.koboo.minestom.stomui.api.item.ViewItem
import net.kyori.adventure.text.Component
import net.kyori.adventure.text.format.NamedTextColor
import net.minestom.server.entity.Player
import net.minestom.server.item.Material
import twizzy.tech.player.PlayerData
import java.math.BigDecimal

class BackpackMenuProvider(
    registry: ViewRegistry,
    private val playerData: PlayerData
) : ViewProvider(registry, ViewBuilder.of(ViewType.SIZE_3_X_9)) {

    override fun modifyBuilder(viewBuilder: ViewBuilder, player: Player) {
        viewBuilder.title("Backpack")
    }

    override fun onOpen(view: PlayerView, player: Player) {
        // Fill with gray glass panes
        for (slot in view.type.topSlots) {
            if (slot != 13) { // Skip the sell button slot
                ViewItem.bySlot(view, slot)
                    .material<ModifiableItem>(Material.GRAY_STAINED_GLASS_PANE)
                    .displayName<ModifiableItem>(" ")
                    .cancelClicking<ModifiableItem>()
            }
        }

        // Add sell button in the middle
        updateSellButton(view, player)
    }

    override fun onRebuild(view: PlayerView, player: Player) {
        // Update the sell button with current data
        updateSellButton(view, player)
    }

    private fun updateSellButton(view: PlayerView, player: Player) {
        val totalItems = playerData.backpack.values.sum()
        val sellValue = twizzy.tech.gameEngine.calculateTotalSellValue(playerData.backpack)

        ViewItem.bySlot(view, 13) // Middle slot (row 2, column 5)
            .material<ModifiableItem>(Material.EMERALD)
            .displayName<ModifiableItem>("§a§lSell Inventory")
            .lore<ModifiableItem>(
                "§7Blocks: §a${String.format("%,d", totalItems)}",
                "§7Value: §e$${"%,.2f".format(sellValue)}",
                "",
                "§eClick to sell all items!"
            )
            .glowing<ModifiableItem>(sellValue > BigDecimal.ZERO)
            .interaction<ModifiableItem>(Interaction { action: ViewAction ->
                handleSellAction(player, view)
            })
    }

    private fun handleSellAction(player: Player, view: PlayerView) {
        val sellValue = twizzy.tech.gameEngine.calculateTotalSellValue(playerData.backpack)

        if (sellValue > BigDecimal.ZERO) {
            playerData.balance = playerData.balance.add(sellValue)
            playerData.backpack.clear()
            player.sendMessage(
                Component.text("Sold your backpack for $${"%,.2f".format(sellValue)}!", NamedTextColor.GREEN)
            )
        } else {
            player.sendMessage(
                Component.text("No valuable items to sell.", NamedTextColor.GRAY)
            )
        }

        // Trigger a rebuild to update the sell button
        view.executeRebuild()
    }
}

package twizzy.tech.commands.shop

import eu.koboo.minestom.stomui.api.interaction.Interactions
import eu.koboo.minestom.stomui.api.item.ModifiableItem
import eu.koboo.minestom.stomui.api.item.ViewItem
import eu.koboo.minestom.stomui.api.pagination.ItemRenderer
import net.minestom.server.entity.Player
import net.minestom.server.item.ItemStack
import net.minestom.server.item.Material

class BlockItemRenderer : ItemRenderer<Material> {

    override fun renderItem(player: Player, viewItem: ViewItem, item: Material) {
        // Get a reasonable price for the block (you can customize this logic)
        val price = getBlockPrice(item)

        viewItem
            .material<ModifiableItem>(item)
            .name<ModifiableItem>("<yellow>${formatMaterialName(item)}")
            .lore<ModifiableItem>(
                "<gray>Price: <green>$${price}",
                "",
                "<yellow>Left click: <white>Buy 1",
                "<yellow>Right click: <white>Buy 64",
                "<yellow>Shift + Left click: <white>Buy stack"
            )
            .interaction<ModifiableItem>(Interactions.leftClick { 
                purchaseBlock(player, item, 1, price)
            })
            .interaction<ModifiableItem>(Interactions.rightClick { 
                purchaseBlock(player, item, 64, price)
            })
            .interaction<ModifiableItem>(Interactions.shiftLeftClick { 
                purchaseBlock(player, item, item.maxStackSize(), price)
            })
    }

    private fun getBlockPrice(material: Material): Double {
        // Simple pricing logic - you can customize this based on your economy
        return when (material) {
            Material.STONE -> 1.0
            Material.COBBLESTONE -> 0.5
            Material.DIRT -> 0.1
            Material.SAND -> 0.2
            Material.GRAVEL -> 0.3
            Material.WOOD, Material.OAK_LOG -> 2.0
            Material.IRON_ORE -> 10.0
            Material.GOLD_ORE -> 25.0
            Material.DIAMOND_ORE -> 100.0
            Material.OBSIDIAN -> 50.0
            else -> {
                // Default pricing based on rarity
                when {
                    material.name().contains("ORE") -> 15.0
                    material.name().contains("LOG") -> 3.0
                    material.name().contains("PLANKS") -> 1.5
                    material.name().contains("STONE") -> 1.0
                    else -> 2.0
                }
            }
        }
    }

    private fun formatMaterialName(material: Material): String {
        return material.name()
            .lowercase()
            .split('_')
            .joinToString(" ") { word ->
                word.replaceFirstChar { if (it.isLowerCase()) it.titlecase() else it.toString() }
            }
    }

    private fun purchaseBlock(player: Player, material: Material, amount: Int, unitPrice: Double) {
        val totalPrice = unitPrice * amount

        // TODO: Check if player has enough money (integrate with your economy system)
        // For now, we'll just give the items

        val itemStack = ItemStack.of(material, amount)
        val success = player.inventory.addItemStack(itemStack)

        if (success) {
            player.sendMessage("<green>Purchased ${amount}x ${formatMaterialName(material)} for $${String.format("%.2f", totalPrice)}")
            // TODO: Deduct money from player's balance
        } else {
            player.sendMessage("<red>Your inventory is full!")
        }
    }
}

package twizzy.tech.commands.shop

import eu.koboo.minestom.stomui.api.pagination.ItemFilter
import net.minestom.server.item.Material

class BlockShopFilter : ItemFilter<Material> {

    private var textInput: String? = null

    fun setTextInput(textInput: String) {
        this.textInput = textInput
    }

    override fun include(item: Material): Boolean {
        // Only include blocks that are items (can be held/placed)
        if (item == Material.AIR || !item.isBlock || !item.isItem) {
            return false
        }

        // No text input → display all block items
        if (textInput.isNullOrEmpty()) {
            return true
        }

        // Check if material name contains the search input
        if (!item.name().lowercase().contains(textInput!!.lowercase())) {
            return false
        }

        return true
    }
}

package twizzy.tech.commands.shop

import eu.koboo.minestom.stomui.api.PlayerView
import eu.koboo.minestom.stomui.api.ViewBuilder
import eu.koboo.minestom.stomui.api.ViewRegistry
import eu.koboo.minestom.stomui.api.ViewType
import eu.koboo.minestom.stomui.api.component.ViewProvider
import eu.koboo.minestom.stomui.api.interaction.AnvilInputInteraction
import eu.koboo.minestom.stomui.api.interaction.Interactions
import eu.koboo.minestom.stomui.api.item.ModifiableItem
import eu.koboo.minestom.stomui.api.item.ViewItem
import eu.koboo.minestom.stomui.api.pagination.ViewPagination
import eu.koboo.minestom.stomui.api.slots.ViewPattern
import net.minestom.server.entity.Player
import net.minestom.server.item.ItemStack
import net.minestom.server.item.Material
import java.util.concurrent.ConcurrentHashMap

class BlockShopProvider(registry: ViewRegistry) :
    ViewProvider(registry, ViewBuilder.of(VIEW_TYPE).title("Block Shop - Search:")),
    AnvilInputInteraction {

    companion object {
        private val VIEW_TYPE = ViewType.ANVIL
        // Store original inventories for each player
        private val savedInventories = ConcurrentHashMap<Player, Array<ItemStack>>()

        fun savePlayerInventory(player: Player) {
            val inventory = player.inventory
            val items = Array(inventory.size) { index ->
                inventory.getItemStack(index)
            }
            savedInventories[player] = items
        }

        fun restorePlayerInventory(player: Player) {
            savedInventories[player]?.let { items ->
                val inventory = player.inventory
                inventory.clear()
                items.forEachIndexed { index, item ->
                    inventory.setItemStack(index, item)
                }
                savedInventories.remove(player)
            }
        }
    }

    private val pattern: ViewPattern
    private val filter: BlockShopFilter
    private val pagination: ViewPagination<Material>

    init {
        pattern = registry.pattern(
            "#########",
            "#########", 
            "#########",
            "A <   >  "
        )
        pattern.offsetTopInventory(VIEW_TYPE)

        pagination = registry.pageable(
            BlockItemRenderer(),
            ItemStack.AIR,
            pattern.getSlots('#')
        )
        pagination.setItemSorter(Comparator.comparing(Material::id))
        filter = BlockShopFilter()
        pagination.setItemFilter(filter)

        // Add all block materials to the shop
        val blockMaterials = Material.values().filter { 
            it.isBlock && it != Material.AIR && it.isItem
        }
        pagination.addItems(blockMaterials)
        addChild(pagination)
    }

    override fun onOpen(view: PlayerView, player: Player) {
        // Save player's inventory when opening the shop
        savePlayerInventory(player)

        view.bottomInventory.clear()

        ViewItem.bySlot(view, 0)
            .material<ModifiableItem>(Material.PAPER)
            .name<ModifiableItem>("")
            .cancelClicking<ModifiableItem>()

        for (slot in pattern.getSlots(' ')) {
            ViewItem.bySlot(view, slot)
                .material<ModifiableItem>(Material.GRAY_STAINED_GLASS_PANE)
                .name<ModifiableItem>(" ")
                .cancelClicking<ModifiableItem>()
        }
    }

    override fun onClose(view: PlayerView, player: Player) {
        // Restore player's inventory when closing the shop
        restorePlayerInventory(player)
        view.bottomInventory.clear()
    }

    override fun onRebuild(view: PlayerView, player: Player) {
        val nextName = if (pagination.hasNextPage()) {
            "<green>Next (${pagination.nextPage})"
        } else {
            "<red>No next page"
        }
        ViewItem.bySlot(view, pattern.getSlot('>'))
            .material<ModifiableItem>(Material.ARROW)
            .name<ModifiableItem>(nextName)
            .glint<ModifiableItem>(pagination.hasNextPage())
            .interaction<ModifiableItem>(Interactions.toNextPage(pagination))

        val previousName = if (pagination.hasPreviousPage()) {
            "<green>Previous (${pagination.previousPage})"
        } else {
            "<red>No previous page"
        }
        ViewItem.bySlot(view, pattern.getSlot('<'))
            .material<ModifiableItem>(Material.ARROW)
            .name<ModifiableItem>(previousName)
            .glint<ModifiableItem>(pagination.hasPreviousPage())
            .interaction<ModifiableItem>(Interactions.toPreviousPage(pagination))

        ViewItem.bySlot(view, pattern.getSlot('A'))
            .material<ModifiableItem>(Material.GOLD_NUGGET)
            .name<ModifiableItem>("<gray>Blocks Available: <gold>${pagination.totalItems}")
            .cancelClicking<ModifiableItem>()
    }

    override fun onAnvilInput(playerView: PlayerView, player: Player, searchInput: String) {
        player.sendMessage("Searching for: $searchInput")
        filter.setTextInput(searchInput)
        pagination.refreshPage(playerView)
    }
}

package twizzy.tech.game.cells

import net.kyori.adventure.text.Component
import net.kyori.adventure.text.event.ClickEvent
import net.kyori.adventure.text.event.HoverEvent
import net.minestom.server.MinecraftServer
import net.minestom.server.entity.Player
import twizzy.tech.util.YamlFactory
import java.util.*
import java.util.concurrent.ConcurrentHashMap
import kotlinx.coroutines.*

/**
 * Represents a cell invitation
 */
data class CellInvitation(
    val cellId: String,
    val cellName: String,
    val inviterId: UUID,
    val inviterName: String,
    val inviteeId: UUID,
    val inviteeName: String,
    val timestamp: Long = System.currentTimeMillis(),
    val expiresAt: Long = System.currentTimeMillis() + INVITATION_TIMEOUT_MS
) {
    companion object {
        const val INVITATION_TIMEOUT_MS = 60_000L // 1 minute timeout
    }

    fun isExpired(): Boolean = System.currentTimeMillis() > expiresAt
    fun getTimeRemaining(): Long = (expiresAt - System.currentTimeMillis()).coerceAtLeast(0L)
}

/**
 * Manages cell invitations with timeout and acceptance/decline functionality
 */
class CellInvitationManager {

    // Store pending invitations: inviteeId -> List of invitations
    private val pendingInvitations = ConcurrentHashMap<UUID, MutableList<CellInvitation>>()

    // Store outgoing invitations: inviterId -> List of sent invitations
    private val sentInvitations = ConcurrentHashMap<UUID, MutableList<CellInvitation>>()

    // Cleanup job for expired invitations
    private var cleanupJob: Job? = null

    companion object {
        private var instance: CellInvitationManager? = null
        private const val MAX_PENDING_INVITES_PER_PLAYER = 5
        private const val MAX_SENT_INVITES_PER_PLAYER = 10

        fun getInstance(): CellInvitationManager {
            if (instance == null) {
                instance = CellInvitationManager()
            }
            return instance!!
        }
    }

    init {
        startCleanupTask()
    }

    /**
     * Sends an invitation from a cell leader to a target player
     */
    suspend fun sendInvitation(
        cellId: String,
        cellName: String,
        inviter: Player,
        targetPlayer: Player
    ): InvitationResult {
        val inviterId = inviter.uuid
        val inviteeId = targetPlayer.uuid

        // Check if player already has too many pending invitations
        val playerInvites = pendingInvitations[inviteeId] ?: mutableListOf()
        if (playerInvites.size >= MAX_PENDING_INVITES_PER_PLAYER) {
            return InvitationResult.TOO_MANY_PENDING
        }

        // Check if inviter has sent too many invitations
        val senderInvites = sentInvitations[inviterId] ?: mutableListOf()
        if (senderInvites.size >= MAX_SENT_INVITES_PER_PLAYER) {
            return InvitationResult.TOO_MANY_SENT
        }

        // Check if there's already a pending invitation from this cell to this player
        if (playerInvites.any { it.cellId == cellId && !it.isExpired() }) {
            return InvitationResult.ALREADY_INVITED
        }

        // Create the invitation
        val invitation = CellInvitation(
            cellId = cellId,
            cellName = cellName,
            inviterId = inviterId,
            inviterName = inviter.username,
            inviteeId = inviteeId,
            inviteeName = targetPlayer.username
        )

        // Add to pending and sent lists
        pendingInvitations.computeIfAbsent(inviteeId) { mutableListOf() }.add(invitation)
        sentInvitations.computeIfAbsent(inviterId) { mutableListOf() }.add(invitation)

        // Send invitation message to target player
        sendInvitationMessage(targetPlayer, invitation)

        // Send confirmation to inviter
        val confirmMessage = YamlFactory.getMessage("commands.cell.invite.sent", mapOf(
            "player" to targetPlayer.username,
            "cell" to cellName
        ))
        inviter.sendMessage(Component.text(confirmMessage))

        return InvitationResult.SUCCESS
    }

    /**
     * Accepts a cell invitation
     */
    suspend fun acceptInvitation(player: Player, cellName: String): AcceptResult {
        val playerId = player.uuid
        val playerInvites = pendingInvitations[playerId] ?: return AcceptResult.NO_INVITATION

        // Find the invitation for the specified cell
        val invitation = playerInvites.find { 
            it.cellName.equals(cellName, ignoreCase = true) && !it.isExpired() 
        } ?: return AcceptResult.NO_INVITATION

        // Check if invitation is expired
        if (invitation.isExpired()) {
            removeInvitation(invitation)
            return AcceptResult.EXPIRED
        }

        // Check if player is already in a cell
        val cellManager = CellManager.getInstance()
        if (cellManager.getPlayerCell(playerId) != null) {
            removeInvitation(invitation)
            return AcceptResult.ALREADY_IN_CELL
        }

        // Check if the cell still exists and isn't full
        val cell = cellManager.getCell(invitation.cellId)
        if (cell == null) {
            removeInvitation(invitation)
            return AcceptResult.CELL_NOT_FOUND
        }

        if (cell.isFull()) {
            removeInvitation(invitation)
            return AcceptResult.CELL_FULL
        }

        // Try to join the cell
        val joinResult = cellManager.joinCell(invitation.cellId, playerId)
        if (joinResult != CellJoinResult.SUCCESS) {
            removeInvitation(invitation)
            return AcceptResult.JOIN_FAILED
        }

        // Remove the invitation and notify both parties
        removeInvitation(invitation)

        // Notify the player
        val joinMessage = YamlFactory.getMessage("commands.cell.invite.accepted_player", mapOf(
            "cell" to invitation.cellName
        ))
        player.sendMessage(Component.text(joinMessage))

        // Notify the inviter if online
        val inviter = MinecraftServer.getConnectionManager().getOnlinePlayerByUuid(invitation.inviterId)
        if (inviter != null) {
            val inviterMessage = YamlFactory.getMessage("commands.cell.invite.accepted_inviter", mapOf(
                "player" to invitation.inviteeName,
                "cell" to invitation.cellName
            ))
            inviter.sendMessage(Component.text(inviterMessage))
        }

        return AcceptResult.SUCCESS
    }

    /**
     * Declines a cell invitation
     */
    suspend fun declineInvitation(player: Player, cellName: String): DeclineResult {
        val playerId = player.uuid
        val playerInvites = pendingInvitations[playerId] ?: return DeclineResult.NO_INVITATION

        // Find the invitation for the specified cell
        val invitation = playerInvites.find { 
            it.cellName.equals(cellName, ignoreCase = true) && !it.isExpired() 
        } ?: return DeclineResult.NO_INVITATION

        // Remove the invitation
        removeInvitation(invitation)

        // Notify the player
        val declineMessage = YamlFactory.getMessage("commands.cell.invite.declined_player", mapOf(
            "cell" to invitation.cellName
        ))
        player.sendMessage(Component.text(declineMessage))

        // Notify the inviter if online
        val inviter = MinecraftServer.getConnectionManager().getOnlinePlayerByUuid(invitation.inviterId)
        if (inviter != null) {
            val inviterMessage = YamlFactory.getMessage("commands.cell.invite.declined_inviter", mapOf(
                "player" to invitation.inviteeName,
                "cell" to invitation.cellName
            ))
            inviter.sendMessage(Component.text(inviterMessage))
        }

        return DeclineResult.SUCCESS
    }

    /**
     * Gets all pending invitations for a player
     */
    fun getPendingInvitations(playerId: UUID): List<CellInvitation> {
        return pendingInvitations[playerId]?.filter { !it.isExpired() } ?: emptyList()
    }

    /**
     * Gets all sent invitations for a player
     */
    fun getSentInvitations(playerId: UUID): List<CellInvitation> {
        return sentInvitations[playerId]?.filter { !it.isExpired() } ?: emptyList()
    }

    /**
     * Cancels a sent invitation
     */
    suspend fun cancelInvitation(inviter: Player, targetPlayerName: String, cellName: String): CancelResult {
        val inviterId = inviter.uuid
        val senderInvites = sentInvitations[inviterId] ?: return CancelResult.NO_INVITATION

        // Find the invitation
        val invitation = senderInvites.find { 
            it.inviteeName.equals(targetPlayerName, ignoreCase = true) && 
            it.cellName.equals(cellName, ignoreCase = true) && 
            !it.isExpired() 
        } ?: return CancelResult.NO_INVITATION

        // Remove the invitation
        removeInvitation(invitation)

        // Notify the inviter
        val cancelMessage = YamlFactory.getMessage("commands.cell.invite.cancelled", mapOf(
            "player" to invitation.inviteeName,
            "cell" to invitation.cellName
        ))
        inviter.sendMessage(Component.text(cancelMessage))

        // Notify the invitee if online
        val invitee = MinecraftServer.getConnectionManager().getOnlinePlayerByUuid(invitation.inviteeId)
        if (invitee != null) {
            val inviteeMessage = YamlFactory.getMessage("commands.cell.invite.cancelled_target", mapOf(
                "cell" to invitation.cellName,
                "inviter" to invitation.inviterName
            ))
            invitee.sendMessage(Component.text(inviteeMessage))
        }

        return CancelResult.SUCCESS
    }

    /**
     * Sends a formatted invitation message to the target player
     */
    private fun sendInvitationMessage(player: Player, invitation: CellInvitation) {
        val timeRemaining = invitation.getTimeRemaining() / 1000 // Convert to seconds

        // Create clickable accept/decline buttons
        val acceptButton = Component.text("§a[ACCEPT]")
            .hoverEvent(HoverEvent.showText(Component.text("§aClick to accept the invitation")))
            .clickEvent(ClickEvent.runCommand("/cell accept ${invitation.cellName}"))

        val declineButton = Component.text("§c[DECLINE]")
            .hoverEvent(HoverEvent.showText(Component.text("§cClick to decline the invitation")))
            .clickEvent(ClickEvent.runCommand("/cell decline ${invitation.cellName}"))

        // Send the invitation message
        val header = YamlFactory.getMessage("commands.cell.invite.received_header")
        val inviteText = YamlFactory.getMessage("commands.cell.invite.received_message", mapOf(
            "inviter" to invitation.inviterName,
            "cell" to invitation.cellName,
            "timeout" to timeRemaining.toString()
        ))
        val footer = YamlFactory.getMessage("commands.cell.invite.received_footer")

        player.sendMessage(Component.text(header))
        player.sendMessage(Component.text(inviteText))
        player.sendMessage(Component.text("§7Click: ").append(acceptButton).append(Component.text(" §7or ")).append(declineButton))
        player.sendMessage(Component.text(footer))
    }

    /**
     * Removes an invitation from both pending and sent lists
     */
    private fun removeInvitation(invitation: CellInvitation) {
        pendingInvitations[invitation.inviteeId]?.remove(invitation)
        sentInvitations[invitation.inviterId]?.remove(invitation)

        // Clean up empty lists
        if (pendingInvitations[invitation.inviteeId]?.isEmpty() == true) {
            pendingInvitations.remove(invitation.inviteeId)
        }
        if (sentInvitations[invitation.inviterId]?.isEmpty() == true) {
            sentInvitations.remove(invitation.inviterId)
        }
    }

    /**
     * Starts the cleanup task for expired invitations
     */
    private fun startCleanupTask() {
        cleanupJob = CoroutineScope(Dispatchers.Default).launch {
            while (true) {
                delay(30_000L) // Clean up every 30 seconds
                cleanupExpiredInvitations()
            }
        }
    }

    /**
     * Removes expired invitations
     */
    private fun cleanupExpiredInvitations() {
        val now = System.currentTimeMillis()

        // Clean up pending invitations
        pendingInvitations.forEach { (playerId, invites) ->
            invites.removeIf { it.isExpired() }
        }
        pendingInvitations.entries.removeIf { it.value.isEmpty() }

        // Clean up sent invitations
        sentInvitations.forEach { (playerId, invites) ->
            invites.removeIf { it.isExpired() }
        }
        sentInvitations.entries.removeIf { it.value.isEmpty() }
    }

    /**
     * Stops the cleanup task
     */
    fun shutdown() {
        cleanupJob?.cancel()
    }
}

// Result enums for invitation operations
enum class InvitationResult {
    SUCCESS,
    TOO_MANY_PENDING,
    TOO_MANY_SENT,
    ALREADY_INVITED
}

enum class AcceptResult {
    SUCCESS,
    NO_INVITATION,
    EXPIRED,
    ALREADY_IN_CELL,
    CELL_NOT_FOUND,
    CELL_FULL,
    JOIN_FAILED
}

enum class DeclineResult {
    SUCCESS,
    NO_INVITATION
}

enum class CancelResult {
    SUCCESS,
    NO_INVITATION
}

package twizzy.tech.game.pets

import java.math.BigDecimal
import java.time.LocalDate
import java.time.LocalDateTime
import java.util.UUID

data class BatData(
    val playerId: UUID,
    var level: Int = 1,
    var soulsCollected: BigDecimal = BigDecimal.ZERO,
    var lastCollectionTime: LocalDateTime = LocalDateTime.now(),
    var lastDailyMining: LocalDate? = null,
    var miningStreak: Int = 0,
    var totalMiningTimeToday: Long = 0 // in seconds
)
